func scalarIntegerParameter(value scalarValue) (int, bool) {
	switch enumValue12 := value; enumValue12.Tag() {
	case scalarValueTagZero:
		panic("zero scalarValue")
	case scalarValueTagBoolean:
		return 0, false
	case scalarValueTagInteger:
		return 0, false
	case scalarValueTagBooleanParameter:
		return 0, false
	case scalarValueTagIntegerParameter:
		parameter := enumValue12.IntegerParameterPayload()
		return parameter.Index, true
	default:
		panic(enumValue12.UnknownTag()) // unreachable: tgolint requires a case per tag
	}
}

func cloneScalarState(state scalarState) scalarState {
	cloned := make(scalarState, len(state))
	for object, value := range state {
		cloned[object] = value
	}
	return cloned
}

// joinScalarState keeps facts that are equal on every incoming path.
func joinScalarState(current scalarState, incoming scalarState) (scalarState, bool) {
	if current == nil {
		return cloneScalarState(incoming), true
	}
	joined := make(scalarState)
	for object, value := range current {
		if other, ok := incoming[object]; ok {
			if scalarValuesEqual(value, other) {
				joined[object] = value
			}
		}
	}
	if scalarStatesEqual(current, joined) {
		return current, false
	}
	return joined, true
}

func scalarStatesEqual(left scalarState, right scalarState) bool {
	if len(left) != len(right) {
		return false
	}
	for object, value := range left {
		if other, ok := right[object]; ok {
			if !scalarValuesEqual(value, other) {
				return false
			}
		} else {
			return false
		}
	}
	return true
}

func recordScalarState(target map[ast.Node]scalarState, root ast.Node, state scalarState) {
	ast.Inspect(root, func(node ast.Node) bool {
		if node == nil {
			return false
		}
		if _, nested := node.(*ast.FuncLit); nested {
			return false
		}
		target[node] = cloneScalarState(state)
		return true
	})
}
